var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
var sb = new System.Text.StringBuilder();
foreach (var root in scene.GetRootGameObjects())
{
    var all = root.GetComponentsInChildren<RectTransform>(true);
    foreach (var rt in all)
    {
        if (!rt.name.StartsWith("Slot ")) continue;
        string path = rt.name;
        var t = rt.parent;
        while (t != null) { path = t.name + "/" + path; t = t.parent; }
        var ap = rt.anchoredPosition;
        var sd = rt.sizeDelta;
        sb.Append(path)
          .Append(" | anchored=").Append(ap.x).Append(",").Append(ap.y)
          .Append(" | sizeDelta=").Append(sd.x).Append(",").Append(sd.y)
          .Append(" | anchorMin=").Append(rt.anchorMin.x).Append(",").Append(rt.anchorMin.y)
          .Append(" | anchorMax=").Append(rt.anchorMax.x).Append(",").Append(rt.anchorMax.y)
          .Append(" | pivot=").Append(rt.pivot.x).Append(",").Append(rt.pivot.y)
          .Append(" | localPos=").Append(rt.localPosition.x).Append(",").Append(rt.localPosition.y).Append(",").Append(rt.localPosition.z)
          .Append("\n");
    }
}
return sb.ToString();
